def monoalpha_decrypt(ciphertext, key, normal='abcdefghijklmnopqrstuvwxyz'):
    decrypt_dict = {key[i]: normal[i] for i in range(len(key))}
    result = ''
    for ch in ciphertext:
        is_upper = ch.isupper()
        ch_low = ch.lower()
        if ch_low in decrypt_dict:
            plain_ch = decrypt_dict[ch_low]
            result += plain_ch.upper() if is_upper else plain_ch
        else:
            result += ch
    return result

